"""Find the TV's current DevTools target and add/remove a temporary image overlay.

Requires websocket-client: python -m pip install websocket-client
No Chrome window is opened. Supports HTTPS images and embedded base64 images.
"""
import argparse
import base64
import binascii
import ipaddress
import json
from pathlib import Path
import socket
import sys
import time
from urllib.parse import urlsplit

import rediscover_devtools as discovery

IMAGE_URL = ("")
OVERLAY_ID = 'vizio-control-meme-img-plug'


def normalize_image_source(value):
    """Accept HTTPS, base64 image data URLs, or raw base64 pasted into IMAGE_URL."""
    value = value.strip()
    if urlsplit(value).scheme == 'https':
        if not urlsplit(value).hostname:
            raise ValueError('HTTPS image URL must include a hostname')
        return value
    declared_mime = None
    payload = value
    if value.startswith('data:'):
        header, separator, payload = value.partition(',')
        if not separator or not header.endswith(';base64'):
            raise ValueError('Use data:image/gif;base64,... or raw base64')
        declared_mime = header[5:-7].lower()
    try:
        payload = ''.join(payload.split())
        decoded = base64.b64decode(payload, validate=True)
    except (ValueError, binascii.Error):
        raise ValueError('Image must be an HTTPS URL, image data URL, or valid raw base64') from None
    if decoded.startswith((b'GIF87a', b'GIF89a')):
        mime = 'image/gif'
    elif decoded.startswith(b'\x89PNG\r\n\x1a\n'):
        mime = 'image/png'
    elif decoded.startswith(b'\xff\xd8\xff'):
        mime = 'image/jpeg'
    elif decoded.startswith(b'RIFF') and decoded[8:12] == b'WEBP':
        mime = 'image/webp'
    else:
        raise ValueError('Base64 does not contain a recognized GIF, PNG, JPEG, or WebP image')
    if declared_mime is not None and declared_mime != mime:
        raise ValueError(f'Data URL MIME type does not match the image; expected {mime}')
    return f'data:{mime};base64,{payload}'


def image_file_source(path):
    """Embed the original bytes; preserve GIF animation and detect the MIME type."""
    payload = Path(path).expanduser().read_bytes()
    return normalize_image_source(base64.b64encode(payload).decode('ascii'))


def overlay_expression(url=IMAGE_URL, remove=False):
    if remove:
        return ('(() => {const img=document.getElementById(' + json.dumps(OVERLAY_ID) + ');'
                'const existed=!!img;if(img)img.remove();return {ok:true,removed:existed};})()')
    return """(async () => {
      const id = __ID__, url = __URL__;
      let img = document.getElementById(id);
      if (img && img.tagName !== 'IMG') return {ok:false, reason:'Overlay ID is already in use'};
      if (!img) { img = document.createElement('img'); img.id = id; }
      img.alt = 'Temporary VizioControl meme overlay';
      img.referrerPolicy = 'no-referrer';
      const styles = {
        position:'fixed', top:'0', left:'0', width:'100%', height:'100%',
        'z-index':'2147483647', 'object-fit':'contain', 'object-position':'center',
        display:'block', visibility:'visible', opacity:'1',
        'pointer-events':'none', margin:'0', padding:'0', border:'0',
        'max-width':'none', 'max-height':'none', transform:'none', animation:'none'
      };
      Object.entries(styles).forEach(([key,value]) => img.style.setProperty(key,value,'important'));
      const loaded = new Promise(resolve => {
        let finished = false;
        const done = ok => { if (!finished) { finished=true; clearTimeout(timer); resolve(ok); } };
        const timer = setTimeout(() => done(false), 15000);
        img.onload = () => done(true);
        img.onerror = () => done(false);
        if (img.src !== url) img.src = url;
        if (img.complete && img.naturalWidth > 0) done(true);
      });
      document.documentElement.appendChild(img);
      const ok = await loaded;
      img.onload = img.onerror = null;
      const box = img.getBoundingClientRect();
      return {
        ok, reason:ok ? null : 'Image failed to load, timed out, or was blocked by page policy',
        id, connected:img.isConnected, naturalWidth:img.naturalWidth, naturalHeight:img.naturalHeight,
        width:box.width, height:box.height, viewportHeight:window.innerHeight,
        zIndex:getComputedStyle(img).zIndex
      };
    })()""".replace('__ID__', json.dumps(OVERLAY_ID)).replace('__URL__', json.dumps(url))


def choose_target(host, port, title_filter=None):
    _, body = discovery.http_get(host, port, '/json/list')
    data = json.loads(body)
    if not isinstance(data, list):
        raise ValueError('Debugger did not return a target list')
    candidates = [item for item in data if isinstance(item, dict) and item.get('type') == 'page'
                  and item.get('webSocketDebuggerUrl')]
    if title_filter:
        candidates = [item for item in candidates if title_filter.casefold() in
                      (str(item.get('title', '')) + ' ' + str(item.get('url', ''))).casefold()]
    if len(candidates) != 1:
        raise ValueError(f'Expected one page target; found {len(candidates)}. '
                         'Use --target with a distinctive page title or URL substring.')
    target = candidates[0]
    address = urlsplit(target['webSocketDebuggerUrl'])
    if (address.scheme != 'ws' or address.hostname != host or address.port != port
            or address.username or address.password or not address.path.startswith('/devtools/page/')):
        raise ValueError('Target WebSocket does not match the requested TV and debugger port')
    return target


def evaluate(ws, expression, timeout=22):
    """One correlated CDP command; ignore unsolicited events until its reply arrives."""
    ws.send(json.dumps({'id': 1, 'method': 'Runtime.evaluate', 'params': {
        'expression': expression, 'awaitPromise': True, 'returnByValue': True}}))
    end = time.monotonic() + timeout
    while time.monotonic() < end:
        ws.settimeout(max(.1, end - time.monotonic()))
        raw = ws.recv()
        if not raw:
            raise ValueError('Debugger disconnected before returning the result')
        message = json.loads(raw)
        if message.get('id') != 1:
            continue
        if message.get('error'):
            raise ValueError('CDP command failed: ' + message['error'].get('message', 'unknown error'))
        result = message.get('result', {})
        if result.get('exceptionDetails'):
            raise ValueError('JavaScript evaluation failed: ' +
                             result['exceptionDetails'].get('text', 'unknown error'))
        value = result.get('result', {}).get('value')
        if not isinstance(value, dict) or not value.get('ok'):
            raise ValueError('Overlay failed: ' + str(value))
        return value
    raise ValueError('Timed out waiting for the debugger')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--host', type=ipaddress.IPv4Address, default='192.168.50.233')
    parser.add_argument('--port', type=int, help='Skip discovery and use this known debugger port')
    parser.add_argument('--target', help='Page title/URL substring if multiple pages are exposed')
    source = parser.add_mutually_exclusive_group()
    source.add_argument('--image-url', default=IMAGE_URL,
                        help='HTTPS URL, base64 image data URL, or raw base64')
    source.add_argument('--image-file', type=Path,
                        help='Local GIF, PNG, JPEG, or WebP file; automatically base64 encoded')
    parser.add_argument('--remove', action='store_true', help='Remove this script\'s overlay instead')
    parser.add_argument('--replay', action='store_true', help='Repeat historical status requests before scanning')
    parser.add_argument('--full', action='store_true', help='Use conservative scan timing')
    args = parser.parse_args(argv)
    if args.port is not None and not 1 <= args.port <= 65535:
        parser.error('--port must be between 1 and 65535')
    if not args.remove:
        try:
            args.image_url = (image_file_source(args.image_file) if args.image_file is not None
                              else normalize_image_source(args.image_url))
        except (ValueError, OSError) as exc:
            parser.error(str(exc))
    try:
        import websocket
    except ImportError:
        print('Install dependency: python -m pip install websocket-client', file=sys.stderr)
        return 1
    host = str(args.host)
    try:
        port = args.port
        if port is None:
            if args.replay:
                discovery.replay(host)
            # Stop at the first confirmed target, even with conservative timing.
            result = discovery.scan(host, 1, 65535, 128 if args.full else 256,
                                    .5 if args.full else .2,
                                    preferred=discovery.cached_ports(host) + discovery.HISTORICAL_PORTS)
            if not result['debuggers']:
                print('No current DevTools page found. Start the app/video and retry.', file=sys.stderr)
                return 2
            port = result['debuggers'][0]['port']
        target = choose_target(host, port, args.target)
        discovery.remember_ports(host, [port])
        print(f'Connecting directly to TV debugger on port {port} (no Chrome).', flush=True)
        # Supplying the connected socket prevents this local connection from
        # being routed through a machine-wide HTTP proxy.
        with socket.create_connection((host, port), timeout=6) as raw:
            ws = websocket.create_connection(target['webSocketDebuggerUrl'], socket=raw,
                                             timeout=22, suppress_origin=True)
            try:
                value = evaluate(ws, overlay_expression(args.image_url, args.remove))
            finally:
                ws.close()
        print(json.dumps(value, indent=2))
        print('Overlay removed.' if args.remove else
              'Image loaded into the page. It lasts until removed or the app reloads.')
        return 0
    except KeyboardInterrupt:
        print('Stopped. An already-added overlay remains until removed or the page reloads.')
        return 130
    except Exception as exc:
        # Do not print WebSocket URLs or tokens from the target response.
        print(f'Failed ({type(exc).__name__}). The app may have restarted, the image may be '
              'blocked, or the connection may have closed. Re-run discovery and try again.', file=sys.stderr)
        if isinstance(exc, ValueError):
            print(str(exc), file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
